        public ulong _uid => uid;

        /// <summary>One leg a trimmed field travels over: the connection, who sends, who receives, whether the field is cut there and how its pack got onto the leg.</summary>
        internal readonly record struct TrimLeg(string conn, string sender, string receiver, bool cut, string route);

        /// <summary>
        /// The refusal for fields that one host would have to take in two wire forms ( see the region "Reject a slot that
        /// would need two wire forms on one host" ): what is wrong and why, a scheme of the legs of every conflict, how
        /// each pack gets onto each leg and the fixes, named with this description's own packs and legs.
        /// </summary>
        static string two_wire_forms_report(List<(HostImpl.PackImpl pack, HostImpl.PackImpl.FieldImpl fld, HostImpl host, bool receiving, List<TrimLeg> legs)> conflicts)
        {
            static string leg_name(TrimLeg l) => $"{l.sender} → {l.receiver} over {l.conn}";

            static string declaration(HostImpl.PackImpl.FieldImpl fld)
            {
                var text = fld.symbol?.DeclaringSyntaxReferences.FirstOrDefault()?.GetSyntax().Parent?.Parent?.ToString() ?? fld._name;
                return string.Join(" ", text.Split((char[])[ ' ', '\t', '\r', '\n' ], StringSplitOptions.RemoveEmptyEntries));
            }

            var sb    = new StringBuilder();
            var packs = conflicts.GroupBy(c => c.pack).ToList();
            var n     = conflicts.Select(c => c.fld).Distinct().Count();

            sb.Append($"The protocol description is refused: {n} trimmed field{(n == 1 ? "" : "s")} of {packs.Count} pack{(packs.Count == 1 ? "" : "s")} would need TWO different wire forms on the same host ( {conflicts.Count} conflict{(conflicts.Count == 1 ? "" : "s")} ).\n");
            sb.Append("""

                      Why this cannot be generated
                        A trim ( ToStream / FromStream / Stream ) names ONE leg: a connection and the host that sends over it. On that
                        leg the field travels in its cut form - raw bytes, or UTF-8 for a string. On every other leg it travels as usual -
                        a typed value, or varint characters for a string. But the code of a pack is generated ONCE per host: one
                        serializer and one parser, shared by every connection that host speaks. When one host takes the same field over
                        a cut leg and over a plain leg, only one of the two forms can be generated, and the other leg would silently
                        write or read the wrong bytes. Nothing on the wire tells the difference: the far end would see a torn payload.

                      """);

            foreach( var group in packs )
            {
                var pack = group.Key;
                sb.Append($"\n━━━━ pack `{pack._name}`   line {pack.line_in_src_code}   {pack.symbol} ━━━━\n");

                HostImpl.PackImpl.FieldImpl? shown = null;
                foreach( var c in group.OrderBy(c => c.fld.line_in_src_code).ThenBy(c => c.host._name) )
                {
                    if( c.fld != shown ) sb.Append($"\n  field `{c.fld._name}`   line {c.fld.line_in_src_code}   {declaration(c.fld)}\n");
                    shown = c.fld;

                    var (cut_form, plain_form) = c.fld.is_String ?
                                                     ("UTF-8", "varint characters") :
                                                     ("raw bytes", "a typed value");
                    var verb = c.receiving ?
                                   "RECEIVES" :
                                   "SENDS";
                    var tool = c.receiving ?
                                   "parser" :
                                   "serializer";

                    sb.Append($"\n      host {c.host._name} {verb} it over {c.legs.Count} legs, with ONE {tool} of `{pack._name}`:\n\n");

                    var arrows = c.legs.Select(l => $"{l.sender} ──[ {l.conn} ]──▶ {l.receiver}").ToList();
                    var width  = arrows.Max(a => a.Length);
                    for( var i = 0; i < c.legs.Count; i++ )
                    {
                        var l = c.legs[i];
                        sb.Append($"          {arrows[i].PadRight(width)}   {(l.cut ? cut_form : plain_form),-17}   {(l.cut ? "trimmed on this leg" : "not trimmed here")}\n");
                    }
                    sb.Append($"          {new string(' ', width)}   ✗ the two forms meet in one {tool} of host {c.host._name}\n\n");

                    sb.Append($"      how `{pack._name}` gets onto each leg:\n");
                    foreach( var l in c.legs ) sb.Append($"          {leg_name(l)}: {l.route}\n");
                }

                // lines of a list inside the text below: the raw string does not indent what is put into it, so the indent is given here
                var cut_legs   = string.Join("\n         ", group.SelectMany(c => c.legs).Where(l => l.cut).Select(leg_name).Distinct());
                var plain_legs = string.Join("\n         ", group.SelectMany(c => c.legs).Where(l => !l.cut).Select(leg_name).Distinct());

                sb.Append($"""

                             How to fix `{pack._name}` - pick one:
                               1. Send it only where it is trimmed. Take `{pack._name}` out of what goes over
                                    {plain_legs}
                                  ( see above how it gets there: usually a set such as `_<( … )>` that lists it for every connection ),
                                  so that it travels only over
                                    {cut_legs}
                               2. Give each leg its own pack - the shape `Bytes` / `BytesTime` use: keep `{pack._name}` with its trims for the
                                  trimmed legs above and declare a copy without trims ( for example `{pack._name}Plain` ) for the others.
                               3. Trim the field on every leg the host takes it over: widen the trim's target ( the `IfSendingFrom` interface
                                  it names ) so that it also covers the legs above that are not trimmed now.

                           """);
            }

            return sb.ToString();
        }

