        /// <summary>The families of roles that name any rule, as they go to the generator: made when the project is sent, every index known by then.</summary>
        List<RoleImpl>? roles_;

        List<RoleImpl> roles => roles_ ??= projects.SelectMany(prj => prj.constants_packs).Where(p => p.is_role && 0 < p.role_rules.Count).Distinct().Select(f => new RoleImpl(this, f)).ToList();

        public object? _roles() => roles.Count == 0 ?
                                       null :
                                       roles;

        public int _roles_len => roles.Count;

        public Project.Role _roles(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot, int item) => roles[item];

        /// <summary>
        /// A family of roles and the rights it gives: the masks of `role_rules` keyed by the indexes the generator knows - a pack by its
        /// index in `packs`, an actor by `connection &lt;&lt; 12 | actor`.
        /// </summary>
        public class RoleImpl : Project.Role{
            readonly HostImpl.PackImpl family;
            readonly byte[]            hosts;

            readonly Dictionary<ushort, ulong> packs  = [];
            readonly Dictionary<uint, ulong>   actors = [];

            Dictionary<ushort, ulong>.Enumerator packs_enum;
            Dictionary<uint, ulong>.Enumerator   actors_enum;

            public RoleImpl(ProjectImpl project, HostImpl.PackImpl family)
            {
                this.family = family;
                hosts       = family.role_hosts.Select(h => (byte)h.idx).ToArray();
                foreach( var (e, rule) in family.role_rules )
                    switch( e )
                    {
                        case HostImpl.PackImpl pack when pack.idx < project.packs.Count && project.packs[pack.idx] == pack: // a pack no host uses is not in `packs`: its idx is stale, and nothing checks it
                            packs[(ushort)pack.idx] = rule.mask;
                            break;
                        case ConnectionImpl.ActorImpl actor:
                            var c = project.connections.FindIndex(c => c.actors.Contains(actor));
                            if( c != -1 ) actors[(uint)(c << 12 | project.connections[c].actors.IndexOf(actor))] = rule.mask;
                            break;
                    }
            }

            public ushort _family => (ushort)family.idx;

            public object? _hosts() => hosts.Length == 0 ?
                                           null :
                                           hosts;

            public int  _hosts_len => hosts.Length;
            public void _hosts(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot, int item, Span<byte> dst) => hosts.AsSpan(item, dst.Length).CopyTo(dst);

            public object? _packs() => packs.Count == 0 ?
                                           null :
                                           packs;

            public int    _packs_len                                                          => packs.Count;
            public void   _packs_Init(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot)  => packs_enum = packs.GetEnumerator();
            public ushort _packs_NextItem_Key(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot)
            {
                packs_enum.MoveNext();
                return packs_enum.Current.Key;
            }

            public ulong _packs_Val(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot) => packs_enum.Current.Value;

            public object? _actors() => actors.Count == 0 ?
                                            null :
                                            actors;

            public int  _actors_len                                                         => actors.Count;
            public void _actors_Init(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot) => actors_enum = actors.GetEnumerator();
            public uint _actors_NextItem_Key(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot)
            {
                actors_enum.MoveNext();
                return actors_enum.Current.Key;
            }

            public ulong _actors_Val(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot) => actors_enum.Current.Value;

            public object? _exclusive() => family.role_exclusive.Count == 0 ?
                                               null :
                                               family.role_exclusive;

            public int   _exclusive_len                                                             => family.role_exclusive.Count;
            public ulong _exclusive(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot, int item) => family.role_exclusive[item];
        }
#endregion

        /// <summary>
        /// Represents the implementation of a Host entity within a project.
        /// </summary>
        public class HostImpl : Entity, Project.Host{
            public byte _uid => (byte)uid;

            /// <summary>
            /// Iterates through packs within the host's scope, applying an action to transmittable packs.
            /// If depth is 0, includes only packs defined directly under the host.
            /// If depth > 0, recursively includes all nested packs within the host.
            /// </summary>
            /// <param name="depth">The depth of scope to traverse (0 for immediate host scope, >0 for deeper scopes).</param>
            /// <param name="dst">The action to apply to each transmittable pack.</param>
            public void for_packs_in_scope(uint depth, Action<PackImpl> dst)
            {
                foreach( var entity in entities.Values.Where(e => e.in_host == this && (0 < depth || e.parent_by_source_code == this)) )
                    if( entity is PackImpl pack && pack.is_transmittable )
                        dst(pack);
            }

            /// <summary>
            /// One language marker of a host's doc comment and the references under it. A language's two bits are the implementation
            /// one (low half) and the hash/equals one (high half): <see cref="Mask"/> holds the bits of the marker's language,
            /// <see cref="Config"/> their values. <see cref="Owner"/> is the host whose comment it is: the host or a modifier of it.
            /// </summary>
            public class LangScope{
                public          uint                                                           Mask;
                public          uint                                                           Config;
                public          HostImpl                                                       Owner = null!;
                public          string                                                         Text  = "", Line = "";
                public readonly List<(ISymbol symbol, bool recursive, string text, string line)> Targets = [];
            }

            public readonly List<LangScope> LangScopes = [];

            /// <summary>
            /// Gets or sets the target languages for which code should be generated for this host.
            /// </summary>
            public Project.Host.Langs _langs { get; set; }

            public override bool included   => _included ?? in_project.included;
            public          bool IsModifier => modify_host != null;

            /// <summary>The families of roles named in the host's doc comment, `/// &lt;see cref='Staff'/&gt;`: the host carries them.</summary>
            public readonly List<INamedTypeSymbol> role_families = [];

            /// <summary>
            /// Initializes a new instance of the <see cref="HostImpl"/> class.
            /// </summary>
            /// <param name="project">The project this host belongs to.</param>
            /// <param name="compilation">The Roslyn compilation object.</param>
            /// <param name="host">The syntax node representing the host's struct declaration.</param>
            public HostImpl(ProjectImpl project, CSharpCompilation compilation, StructDeclarationSyntax host) : base(project, compilation, host)
            {
                // 0xFFFFFFFF means:
                // Low 16 bits (0xFFFF): All languages implement the pack/field
                // High 16 bits (0xFFFF): All languages generate Hash/Equals
                _default_impl_hash_equal = 0xFFFF_FFFF;
                project.hosts.Add(this);
            }

            /// <summary>
            /// Gets the host being modified by this host, if this host is a modifier.
            /// Returns null if this host is not a modifier.
            /// </summary>
            public HostImpl? modify_host => equals(symbol!.Interfaces[0].ConstructedFrom, Meta_Modify_Target) ?
                                                (HostImpl)entities[symbol!.Interfaces[0].TypeArguments[0]] :
                                                null;

#region Pack implementation hash and equals configuration
            /// <summary>
            /// Dictionary to store pack-specific implementation configurations for hash code and equals methods.
            /// Key: Symbol representing the pack.
            /// Value: Implementation flags in the Low 16 bits and Hash/Equals flags in the High 16 bits.
            /// </summary>
            public readonly Dictionary<ISymbol, uint> pack_impl = new(SymbolEqualityComparer.Default); //pack -> impl information

            /// <summary>
            /// Enumerator for iterating over the <see cref="pack_impl"/> dictionary.
            /// </summary>
            Dictionary<ISymbol, uint>.Enumerator pack_impl_enum;

            /// <summary>
            /// Provides access to the pack implementation hash and equals configuration dictionary for serialization purposes.
            /// Returns null if the dictionary is empty.
            /// </summary>
            /// <returns>The pack implementation hash and equals configuration dictionary or null if empty.</returns>
            public object? _pack_impl_hash_equal() => pack_impl.Count == 0 ?
                                                          null :
                                                          pack_impl;

            /// <summary>
            /// Gets the count of pack implementation hash and equals configurations.
            /// </summary>
            public int _pack_impl_hash_equal_len => pack_impl.Count;

            /// <summary>
            /// Initializes the enumerator for iterating over the <see cref="pack_impl"/> dictionary during serialization.
            /// </summary>
            /// <param name="ctx">The transmitter context (not used here).</param>
            /// <param name="__slot">The transmitter slot (not used here).</param>
            public void _pack_impl_hash_equal_Init(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot) => pack_impl_enum = pack_impl.GetEnumerator();


            /// <summary>
            /// Moves to the next item in the <see cref="pack_impl"/> dictionary and retrieves the key (pack index).
            /// </summary>
            /// <param name="ctx">The transmitter context (not used here).</param>
            /// <param name="__slot">The transmitter slot (not used here).</param>
            /// <returns>The index of the next pack.</returns>
            public ushort _pack_impl_hash_equal_NextItem_Key(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot)
            {
                pack_impl_enum.MoveNext();
                return (ushort)entities[pack_impl_enum.Current.Key].idx;
            }

            /// <summary>
            /// Retrieves the value (configuration flags) for the current item in the <see cref="pack_impl"/> dictionary.
            /// </summary>
            /// <param name="ctx">The transmitter context (not used here).</param>
            /// <param name="__slot">The transmitter slot (not used here).</param>
            /// <returns>The configuration flags for the current pack.</returns>
            public uint _pack_impl_hash_equal_Val(Base_.Transmitter ctx, Base_.Transmitter.Slot __slot) => pack_impl_enum.Current.Value;

            /// <summary>
            /// Default implementation configuration for hash code and equals methods.
            /// By default, auto-generation is enabled for all languages.
            /// </summary>
            public uint _default_impl_hash_equal { get; set; } //by default a bit per language
#endregion

